"use client";
import { useEffect, useState } from "react";
import { Clock, Save } from "lucide-react";
import { api, ApiError } from "@/lib/api-client";
type Hour={dayOfWeek:number;day:string;isOpen:boolean;openTime:string|null;closeTime:string|null};
const TIME_OPTIONS=Array.from({length:48},(_,i)=>{const minutes=i*30;const h=Math.floor(minutes/60);const m=minutes%60;const value=`${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}`;const hour12=h%12||12;const suffix=h<12?"AM":"PM";return {value,label:`${hour12}:${String(m).padStart(2,"0")} ${suffix}`};});
function normalizeTime(value:string|null){if(!value)return null;const match=value.match(/^(\d{1,2}):(\d{2})(?:\s*(AM|PM))?$/i);if(!match)return value;let hour=Number(match[1]);const minute=match[2];const meridiem=match[3]?.toUpperCase();if(meridiem){if(hour===12)hour=0;if(meridiem==="PM")hour+=12;}return String(hour).padStart(2,"0")+":"+minute;}
function TimeSelect({value,onChange,disabled}:{value:string|null;onChange:(value:string)=>void;disabled:boolean}){return <select value={value??""} disabled={disabled} onChange={e=>onChange(e.target.value)} aria-label="Business hour time" className="w-full rounded-lg border border-graphite-200 bg-white px-3 py-2 text-sm text-graphite-900 dark:border-graphite-700 dark:bg-graphite-950 dark:text-white sm:w-36"><option value="" disabled>Select time</option>{TIME_OPTIONS.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select>;}

export default function BusinessHoursPage(){
 const [hours,setHours]=useState<Hour[]>([]); const [loading,setLoading]=useState(true); const [saving,setSaving]=useState(false); const [message,setMessage]=useState<string|null>(null); const [error,setError]=useState<string|null>(null);
 useEffect(()=>{void api.get<{hours:Hour[]}>("/api/store-hours/me").then(r=>setHours(r.hours.map(h=>({...h,openTime:normalizeTime(h.openTime),closeTime:normalizeTime(h.closeTime)})))).catch(e=>setError(e instanceof ApiError?e.message:"Couldn't load business hours.")).finally(()=>setLoading(false));},[]);
 function update(i:number,patch:Partial<Hour>){setHours(h=>h.map((x,n)=>n===i?{...x,...patch}:x));}
 async function save(){setSaving(true);setError(null);setMessage(null);try{const payload=hours.map(h=>({...h,openTime:h.isOpen?normalizeTime(h.openTime):null,closeTime:h.isOpen?normalizeTime(h.closeTime):null}));if(payload.some(h=>h.isOpen&&(!h.openTime||!h.closeTime))){setError("Please select opening and closing times for every open day.");setSaving(false);return;}await api.put("/api/store-hours/me",{hours:payload});setMessage("Business hours saved.");}catch(e){setError(e instanceof ApiError?e.message:"Couldn't save business hours.");}finally{setSaving(false);}}
 return <main className="shell py-8"><div className="mx-auto max-w-3xl"><div className="flex items-start gap-3"><span className="grid h-11 w-11 place-items-center rounded-card bg-ember-100 text-ember-700"><Clock className="h-5 w-5"/></span><div><h1 className="text-2xl font-bold text-graphite-900 dark:text-white">Business hours</h1><p className="mt-1 text-sm text-graphite-600 dark:text-graphite-400">Tell customers when your store is normally available. Times use Nigeria time (WAT).</p></div></div>{loading?<p className="mt-8 text-sm">Loading…</p>:<div className="mt-7 space-y-3">{hours.map((h,i)=><div key={h.dayOfWeek} className="rounded-card border border-graphite-200 bg-white p-4 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><div className="w-28 font-semibold text-graphite-900 dark:text-white">{h.day}</div><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={h.isOpen} onChange={e=>update(i,{isOpen:e.target.checked})}/><span>{h.isOpen?"Open":"Closed"}</span></label><TimeSelect value={h.openTime} disabled={!h.isOpen} onChange={value=>update(i,{openTime:value})}/><span className="text-sm text-graphite-400">to</span><TimeSelect value={h.closeTime} disabled={!h.isOpen} onChange={value=>update(i,{closeTime:value})}/></div></div>)}</div>}{error&&<p className="mt-4 text-sm font-semibold text-ember-700">{error}</p>}{message&&<p className="mt-4 text-sm font-semibold text-verified-700">{message}</p>}<button disabled={loading||saving} onClick={()=>void save()} className="mt-6 inline-flex items-center gap-2 rounded-card bg-ember-600 px-5 py-3 text-sm font-bold text-white disabled:opacity-50"><Save className="h-4 w-4"/>{saving?"Saving…":"Save business hours"}</button></div></main>;
}